      selectedId={selectedId}
      sweeping={!replayDay}

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

/** The Radar fits its window (knowledge-base/features/ops-control-panel.md §6b): the scope takes the height left between
 * its heading and the telemetry strip, so nothing it holds can push the strip below the fold. A size derived from
 * `100vh` minus a guessed allowance for everything else broke whenever anything else changed height. */
const read = (rel: string) => readFileSync(fileURLToPath(new URL(rel, import.meta.url)), "utf8");
const css = read("./radar.css");

describe("the Radar's size", () => {
  it("is never a guess: no rule takes the viewport height minus a fixed allowance", () => {
    expect(css).not.toMatch(/calc\(\s*100d?vh\s*-/);
  });

  it("the scope is the square that fits the space its box is given, at most 800px", () => {
    expect(css).toMatch(/\.radar-scope-fit\s*{[^}]*container-type:\s*size/);
    expect(css).toMatch(/\.radar-scope\s*{[^}]*width:\s*min\(\s*100cqw,\s*100cqh,\s*800px\s*\)/);
  });

  it("the centre dot and its outward ping are centred on the scope's centre: their border counts inside their 14px", () => {
    const rule = /\.radar-centre,\s*\.radar-centre-ping\s*{([^}]*)}/.exec(css)?.[1] ?? "";
    expect(rule).toMatch(/width:\s*14px/);
    expect(rule).toMatch(/margin:\s*-7px 0 0 -7px/);
    expect(rule).toMatch(/box-sizing:\s*border-box/);
  });
});

describe("beside the feed, an overflowing feed scrolls inside its own column", () => {
  const wide = css.slice(css.indexOf("@media (min-width: 1041px)"));
  const block = wide.slice(0, wide.indexOf("@media (max-width: 1040px)"));

  it("a selected item's banner plus the list's floor cannot push the whole screen: the feed column has its own scroll", () => {
    expect(block).toMatch(/\.radar-feed\s*{[^}]*overflow-y:\s*auto/);
  });
});

describe("the scope's heading drops whole parts, never clips one", () => {
  const rule = (selector: string) => new RegExp(`${selector.replace(/[.>*]/g, "\\$&")}\\s*{([^}]*)}`).exec(css)?.[1] ?? "";

  it("is one fixed row that wraps what does not fit out of sight, so a part is shown whole or not at all", () => {
    const info = rule(".radar-toolbar-info");
    expect(info).toMatch(/flex-wrap:\s*wrap/);
    expect(info).toMatch(/overflow:\s*hidden/);
    expect(info).toMatch(/height:/);
    expect(info).not.toMatch(/flex-wrap:\s*nowrap/);
  });

  it("the note is the part that shortens, down to a floor, so it is cut with an ellipsis before it is dropped", () => {
    const note = rule(".radar-toolbar-info > .radar-toolbar-note");
    expect(note).toMatch(/max-width:\s*max-content/);
    expect(note).toMatch(/text-overflow:\s*ellipsis/);
  });
});
